import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTeachers() {
  const [teachers, setTeachers] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  
  const [formData, setFormData] = useState({ name: '', username: '', subject: '', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' });

  const fetchTeachers = () => axios.get('http://localhost:8081/api/view-teachers').then(res => setTeachers(res.data));
  const fetchSubjects = () => axios.get('http://localhost:8081/api/view-subjects').then(res => setSubjects(res.data));

  useEffect(() => { fetchTeachers(); fetchSubjects(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const apiPath = isEditing ? `http://localhost:8081/api/edit-teacher/${editId}` : 'http://localhost:8081/api/add-teacher';
    const method = isEditing ? axios.put : axios.post;

    method(apiPath, formData).then((res) => { 
        if(res.data.status === "Error") alert("Error: " + res.data.error); 
        else { fetchTeachers(); resetForm(); }
    }).catch(() => alert("Server Error!"));
  };

  const handleEdit = (t) => {
    setIsEditing(true); setEditId(t.id);
    setFormData({ name: t.name, subject: t.Subject || '', qualifications: t.qualifications || '', email: t.email || '', phone_number: t.phone_number, address: t.address || '' });
    setShowForm(true);
  };

  const resetForm = () => { setShowForm(false); setIsEditing(false); setEditId(null); setFormData({ name: '', username: '', subject: '', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' }); };

  const filteredTeachers = teachers.filter(t => t.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif', backgroundColor: '#f8fafc', minHeight: '100vh', animation: 'fadeIn 0.5s' }}>
      
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#fff', padding: '20px 30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', marginBottom: '25px' }}>
        <h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px', display: 'flex', alignItems: 'center', gap: '10px' }}>👩‍🏫 Manage Teachers</h2>
        <div style={{ display: 'flex', gap: '15px' }}>
          <input type="text" placeholder="Search Teacher..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={styles.searchInput} />
          <button onClick={() => {resetForm(); setShowForm(true);}} style={styles.primaryBtn}>+ Add New Teacher</button>
        </div>
      </div>

      <div style={styles.tableContainer}>
        <table style={styles.table}>
          <thead>
            <tr style={{ backgroundColor: '#f1f5f9' }}>
              <th style={styles.th}>Full Name</th><th style={styles.th}>Teaching Subject</th><th style={styles.th}>Qualifications</th><th style={styles.th}>Contact Details</th><th style={styles.th}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredTeachers.map((t, index) => (
              <tr key={t.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={{...styles.td, fontWeight: 'bold', color: '#15803d'}}>{t.name}</td>
                <td style={{...styles.td, color: '#0369a1', fontWeight: 'bold'}}>{t.Subject || '-'}</td>
                <td style={{...styles.td, color: '#475569'}}>{t.qualifications || '-'}</td>
                <td style={{...styles.td, color: '#475569'}}>📞 {t.phone_number}<br/><span style={{fontSize: '12px', color: '#94a3b8'}}>✉️ {t.email || 'N/A'}</span></td>
                <td style={styles.td}><button onClick={() => handleEdit(t)} style={styles.editBtn}>✏️ Edit</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <h3 style={styles.modalTitle}>{isEditing ? '✏️ Edit Teacher' : '➕ Add New Teacher'}</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <input type="text" placeholder="Teacher Full Name" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required style={styles.input} />
              
              {!isEditing && (
                <>
                  <input type="text" placeholder="Login Username" value={formData.username} onChange={e => setFormData({...formData, username: e.target.value})} required style={styles.input} />
                  <input type="text" placeholder="Default Password (TC@123)" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} required style={styles.input} />
                </>
              )}

              <select value={formData.subject} onChange={e => setFormData({...formData, subject: e.target.value})} style={styles.input} required>
                <option value="">-- Select Teaching Subject --</option>
                {subjects.map(s => <option key={s.id} value={s.subject_name}>{s.subject_name}</option>)}
              </select>

              <input type="text" placeholder="Qualifications (e.g. B.Sc, PGDE)" value={formData.qualifications} onChange={e => setFormData({...formData, qualifications: e.target.value})} style={styles.input} />
              <input type="text" placeholder="Contact Number" value={formData.phone_number} onChange={e => setFormData({...formData, phone_number: e.target.value})} required style={styles.input} />
              <input type="email" placeholder="Email Address (Optional)" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} style={styles.input} />

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '10px' }}>
                <button type="button" onClick={resetForm} style={styles.cancelBtn}>Cancel</button>
                <button type="submit" style={styles.saveBtn}>{isEditing ? 'Update Details' : 'Save Teacher'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
